# ──────────────────────────── Logic ────────────────────────────
COMMITTEE_MAP = {
    "AI & ML": 1, "Cybersecurity": 2, "Web Development": 3,
    "Open Source": 4, "UI/UX": 5, "Media": 6, "Design": 7,
}

# ── Alias table: maps any known spelling variant → canonical committee name ──
COMMITTEE_ALIASES: dict[str, str] = {
    # Cyber Security
    "cybersecurity": "Cybersecurity",
    "cyber security": "Cybersecurity",
    "cyber-security": "Cybersecurity",
    "cyber_security": "Cybersecurity",
    # AI
    "ai": "AI & ML",
    "a.i": "AI & ML",
    "ai & ml": "AI & ML",
    "ai&ml": "AI & ML",
    "ai and ml": "AI & ML",
    "ai/ml": "AI & ML",
    "artificial intelligence": "AI & ML",
    # Web
    "web": "Web Development",
    "web development": "Web Development",
    "webdev": "Web Development",
    "web dev": "Web Development",
    # Open Source
    "open source": "Open Source",
    "opensource": "Open Source",
    "open-source": "Open Source",
    # UI/UX
    "ui/ux": "UI/UX",
    "uiux": "UI/UX",
    "ui ux": "UI/UX",
    "ui-ux": "UI/UX",
    "ux/ui": "UI/UX",
    # Media
    "media": "Media",
    # Design
    "design": "Design",
}

def normalize_committee(name: str) -> str:
    """Return the canonical committee name for any known spelling variant."""
    return COMMITTEE_ALIASES.get(name.strip().lower(), name.strip())

def parse_committees(cell_value) -> list:
    """Split a cell that may list multiple committees (comma-separated) and normalize each."""
    raw = str(cell_value).strip()
    if raw.lower() in ("", "nan", "n/a", "none"):
        return ["Unknown"]
    return [normalize_committee(part) for part in raw.split(",") if part.strip()]

def sanitize_sheet_name(name: str) -> str:
    """Remove characters Excel forbids in sheet names and cap at 31 characters."""
    for ch in r'\/:*?[]':
        name = name.replace(ch, "-")
    return name[:31].strip()

def generate_custom_id(year: int, committee: str, member_id: int) -> str:
    yy = str(year)[-2:]                            
    c = str(COMMITTEE_MAP.get(committee, 0))                
    iii = str(int(member_id)).zfill(3)                      
    return f"{yy}{c}{iii}"

def generate_qr_base64(
    full_name: str, custom_id: str, email: str, phone: str,
    faculty: str, specialization: str, university_id: str,
    national_id: str, housing: str, committee: str
) -> str:
    qr_data = (
        f"Name: {full_name}\n"
        f"Volunteer ID: {custom_id}\n"
        f"Committee: {committee}\n"
        f"Email: {email}\n"
        f"Phone: {phone}\n"
        f"Faculty: {faculty}\n"
        f"Specialization: {specialization}\n"
        f"University ID: {university_id}\n"
        f"National ID: {national_id}\n"
        f"Housing: {housing}"
    )
    qr = qrcode.QRCode(version=1, error_correction=qrcode.constants.ERROR_CORRECT_H, box_size=10, border=4)
    qr.add_data(qr_data)
    qr.make(fit=True)
    img = qr.make_image(fill_color="black", back_color="white").convert("RGB")
    buffer = io.BytesIO()
    img.save(buffer, format="PNG")
    buffer.seek(0)
    return base64.b64encode(buffer.read()).decode("utf-8")

# ──────────────────────────── UI ────────────────────────────
st.set_page_config(page_title="IEEE ID Generator", page_icon="🪪")

st.title("🪪 Volunteer ID Card Generator")
st.markdown("Upload an Excel file with volunteer information. The system will generate a PDF ID card for **every** row and provide a ZIP download.")

uploaded_file = st.file_uploader("Upload volunteers Excel file", type=["xlsx"])

if uploaded_file is not None:
    if st.button("Generate Cards", type="primary"):
        with st.spinner("Processing data and rendering PDFs..."):

            # Read Data
            df = pd.read_excel(uploaded_file, engine="openpyxl")
            df.columns = df.columns.str.strip()

            # Extract year from filename if available (e.g. "Volunteers_2027.xlsx" → year=2027)
            import os
            filename_no_ext = os.path.splitext(uploaded_file.name)[0].strip()
            parts = filename_no_ext.rsplit("_", 1)
            if len(parts) == 2 and parts[1].strip().isdigit():
                year_str = parts[1].strip()
                valid_year = int(year_str) if len(year_str) == 4 else int(f"20{year_str}")
            else:
                valid_year = datetime.now().year

            # Detect the committee column (case-insensitive search)
            committee_col = next(
                (c for c in df.columns if c.strip().lower() == "committee"), None
            )
            if committee_col is None:
                st.error("❌ No 'Committee' column found in the uploaded file. Please make sure the sheet has a column named 'Committee'.")
                st.stop()

            st.info(f"📋 Year: **{valid_year}**")

            if df.empty:
                st.info("ℹ️ The uploaded sheet is empty.")
                st.stop()

            # Create "Member ID" column if it doesn't exist
            if "Member ID" not in df.columns:
                df["Member ID"] = pd.NA

            # Setup Jinja Environment
            env = Environment(loader=DictLoader({'template': HTML_TEMPLATE}))
            template = env.get_template('template')

            # Create an in-memory ZIP file
            zip_buffer = io.BytesIO()
            with zipfile.ZipFile(zip_buffer, "a", zipfile.ZIP_DEFLATED, False) as zip_file:

                # ── Process Cards ──────────────────────────────────────────────
                # Volunteers may belong to multiple committees (comma-separated).
                # Each (volunteer, committee) pair gets its own ID and PDF card.
                # committee_records accumulates rows for per-committee Excel sheets.
                progress_bar = st.progress(0)
                total = len(df)
                committee_seq_counters: dict = {}   # committee → next sequence number
                committee_records: dict = {}         # committee → list of row dicts
                all_ids_per_row: dict = {}           # original df index → list of IDs
                card_count = 0

                def safe_col(col, row):
                    return str(row[col]).strip() if col in df.columns else "N/A"

                for i, (idx, row) in enumerate(df.iterrows()):
                    name_parts = str(row["Name"]).strip().split()
                    full_name  = " ".join(name_parts[:3])
                    first_name = name_parts[0] if name_parts else "Unknown"

                    # Parse & normalize — supports multi-committee cells like "Media, Design"
                    committees = parse_committees(row[committee_col])

                    email          = safe_col("Email address", row)
                    phone          = safe_col("Phone Number", row)
                    faculty        = safe_col("Faculty", row)
                    specialization = safe_col("Specialization", row)
                    university_id  = safe_col("University ID", row)
                    national_id    = safe_col("National ID", row)
                    housing        = safe_col("Housing", row)

                    row_ids = []
                    for committee in committees:
                        # Sequential ID scoped per committee
                        committee_seq_counters[committee] = committee_seq_counters.get(committee, 0) + 1
                        custom_id = generate_custom_id(valid_year, committee, committee_seq_counters[committee])
                        row_ids.append(custom_id)

                        # Accumulate data for per-committee Excel sheet
                        record = row.to_dict()
                        record["Member ID"] = custom_id
                        # Drop the original committee column — redundant since sheet name shows it
                        record.pop(committee_col, None)
                        committee_records.setdefault(committee, []).append(record)

                        # Generate QR & PDF card
                        qr_b64 = generate_qr_base64(
                            full_name, custom_id, email, phone,
                            faculty, specialization, university_id,
                            national_id, housing, committee
                        )
                        rendered_html = template.render(
                            name=full_name, committee=committee,
                            generated_id=custom_id, valid_year=valid_year, qr_base64=qr_b64
                        )
                        pdf_buffer = io.BytesIO()
                        weasyprint.HTML(string=rendered_html).write_pdf(pdf_buffer)
                        # PDFs live in per-committee subfolders
                        zip_file.writestr(
                            f"Cards/{sanitize_sheet_name(committee)}/{custom_id}_{first_name}.pdf",
                            pdf_buffer.getvalue()
                        )
                        card_count += 1

                    all_ids_per_row[idx] = ", ".join(row_ids)
                    progress_bar.progress((i + 1) / total)

                # Write back all generated IDs to the summary dataframe
                df["Member ID"] = df.index.map(lambda ix: all_ids_per_row.get(ix, ""))

                # ── Build multi-sheet Excel ────────────────────────────────────
                excel_buffer = io.BytesIO()
                with pd.ExcelWriter(excel_buffer, engine="openpyxl") as writer:
                    # First sheet: every volunteer with all their IDs (includes original committee column)
                    df.to_excel(writer, sheet_name="All Volunteers", index=False)
                    # One sheet per committee (sheet names sanitized for Excel rules)
                    seen_sheets: set = set()
                    for committee_name in sorted(committee_records.keys()):
                        raw_sheet = sanitize_sheet_name(committee_name)
                        sheet_name = raw_sheet
                        suffix = 2
                        while sheet_name in seen_sheets:
                            sheet_name = f"{raw_sheet[:28]}_{suffix}"
                            suffix += 1
                        seen_sheets.add(sheet_name)
                        pd.DataFrame(committee_records[committee_name]).to_excel(
                            writer, sheet_name=sheet_name, index=False
                        )
                zip_file.writestr("volunteers_with_ids.xlsx", excel_buffer.getvalue())

            st.success(f"✅ Successfully generated {card_count} ID card(s) for {total} volunteer(s) across {len(committee_records)} committee(s)!")

            # Download Button
            zip_buffer.seek(0)
            st.download_button(
                label="📥 Download Output Package (.zip)",
                data=zip_buffer,
                file_name=f"Generated_Cards_{datetime.now().strftime('%Y%m%d')}.zip",
                mime="application/zip",
                type="primary"
            )